begin;
create temporary table handoff_test as select gen_random_uuid() as business,gen_random_uuid() as other_business,gen_random_uuid() as day,gen_random_uuid() as a,gen_random_uuid() as b,gen_random_uuid() as c,gen_random_uuid() as outsider,gen_random_uuid() as first_stop,gen_random_uuid() as ready_stop,gen_random_uuid() as done_stop,gen_random_uuid() as other_stop;
insert into auth.users(id,email,email_confirmed_at) select x,'rollback-'||x||'@example.invalid',now() from handoff_test t cross join lateral unnest(array[t.a,t.b,t.c,t.outsider]) x;
insert into public.bjta_businesses(id,name) select business,'Handoff rollback fixture' from handoff_test union all select other_business,'Other rollback fixture' from handoff_test;
insert into public.bjta_staff(business_id,user_id,display_name,roles,active) select business,x,'Fixture driver',array['driver'],true from handoff_test t cross join lateral unnest(array[t.a,t.b,t.c]) x;
insert into public.bjta_staff(business_id,user_id,display_name,roles,active) select other_business,outsider,'Outside driver',array['driver'],true from handoff_test;
select set_config('request.jwt.claim.sub',a::text,true) from handoff_test;
insert into public.bjta_days(id,business_id,delivery_date,kitchen_address) select day,business,current_date,'Fixture kitchen' from handoff_test;
insert into public.bjta_deliveries(id,day_id,details,status,claimed_by,started_at,paid,payment_method,completed_at)
 select first_stop,day,'{"name":"Fixture One","address":"Fixture address","items":[{"name":"Tchaka","qty":2,"price":10}]}'::jsonb,'in_progress',a,now(),false,null,null::timestamptz from handoff_test
 union all select ready_stop,day,'{"name":"Fixture Two","address":"Fixture address"}'::jsonb,'ready',null,null,false,null,null::timestamptz from handoff_test
 union all select done_stop,day,'{"name":"Fixture Done","address":"Fixture address"}'::jsonb,'delivered',a,now(),true,'Cash',now() from handoff_test
 union all select other_stop,day,'{"name":"Other Driver","address":"Fixture address"}'::jsonb,'in_progress',c,now(),false,null,null::timestamptz from handoff_test;
create temporary table original_completed as select to_jsonb(d) as value from public.bjta_deliveries d join handoff_test t on d.id=t.done_stop;
create function pg_temp.expect_error(statement text, expected text) returns void language plpgsql as $$begin begin execute statement;exception when others then if position(expected in sqlerrm)>0 then return;else raise;end if;end;raise exception 'Expected failure: %',expected;end$$;
select set_config('request.jwt.claim.sub',a::text,true) from handoff_test;
select pg_temp.expect_error(format('select public.gldd_request_handoff(%L,%L,%L,array[%L]::uuid[],%L,%L)',day,a,b,done_stop,'Flat tire','Fixture meeting'),'Some stops changed') from handoff_test;
select pg_temp.expect_error(format('select public.gldd_request_handoff(%L,%L,%L,array[%L]::uuid[],%L,%L)',day,a,b,ready_stop,'Flat tire','Fixture meeting'),'Some stops changed') from handoff_test;
select pg_temp.expect_error(format('select public.gldd_request_handoff(%L,%L,%L,array[%L]::uuid[],%L,%L)',day,a,b,other_stop,'Flat tire','Fixture meeting'),'Some stops changed') from handoff_test;
select set_config('request.jwt.claim.sub',(select user_id::text from gldd_private.app_owner limit 1),true);
create temporary table first_handoff as select public.gldd_request_handoff(day,a,b,array[first_stop,ready_stop],'Flat tire','Fixture meeting') as id from handoff_test;
select pg_temp.expect_error(format('select public.gldd_request_handoff(%L,%L,%L,array[%L]::uuid[],%L,%L)',day,a,c,first_stop,'Duplicate','Fixture meeting'),'already has a pending handoff') from handoff_test;
select set_config('request.jwt.claim.sub',a::text,true) from handoff_test;
select pg_temp.expect_error(format('select public.bjta_complete_delivery(%L,true,%L)',first_stop,'Cash'),'paused for handoff') from handoff_test;
select pg_temp.expect_error(format('select public.bjta_start_delivery(%L)',ready_stop),'paused for handoff') from handoff_test;
select pg_temp.expect_error(format('select public.gldd_decide_handoff(%L,%L,true)',id,'accepted'),'Only the replacement') from first_handoff;
select set_config('request.jwt.claim.sub',b::text,true) from handoff_test;
select pg_temp.expect_error(format('select public.gldd_decide_handoff(%L,%L,false)',id,'accepted'),'Confirm you have received') from first_handoff;
select public.gldd_decide_handoff(id,'accepted',true) from first_handoff;
do $$declare t record;begin select * into t from handoff_test;if (select count(*) from public.bjta_deliveries where id=any(array[t.first_stop,t.ready_stop]) and assigned_to=t.b and status='ready' and claimed_by is null)<>2 then raise exception 'Assignment failed';end if;end$$;
select pg_temp.expect_error(format('select public.gldd_decide_handoff(%L,%L,true)',id,'accepted'),'already been handled') from first_handoff;
select set_config('request.jwt.claim.sub',a::text,true) from handoff_test;
select pg_temp.expect_error(format('select public.bjta_start_delivery(%L)',first_stop),'assigned to another driver') from handoff_test;
select pg_temp.expect_error(format('select public.bjta_complete_delivery(%L,true,%L)',first_stop,'Cash'),'Only the staff member') from handoff_test;
select set_config('request.jwt.claim.sub',b::text,true) from handoff_test;
select (public.bjta_start_delivery(first_stop)).status from handoff_test;
select (public.bjta_complete_delivery(first_stop,true,'Zelle')).status from handoff_test;
select pg_temp.expect_error(format('select public.bjta_complete_delivery(%L,true,%L)',first_stop,'Zelle'),'Only the staff member') from handoff_test;
create temporary table next_handoff as select public.gldd_request_handoff(day,b,c,array[ready_stop],'Vehicle issue','Fixture meeting') as id from handoff_test;
select set_config('request.jwt.claim.sub',c::text,true) from handoff_test;
select public.gldd_decide_handoff(id,'declined',false) from next_handoff;
do $$declare t record;begin select * into t from handoff_test;if not exists(select 1 from public.bjta_deliveries where id=t.ready_stop and assigned_to=t.b and status='ready') then raise exception 'Decline changed assignment';end if;end$$;
select set_config('request.jwt.claim.sub',b::text,true) from handoff_test;
create temporary table cancel_handoff as select public.gldd_request_handoff(day,b,c,array[ready_stop],'Vehicle issue','Fixture meeting') as id from handoff_test;
select public.gldd_decide_handoff(id,'cancelled',false) from cancel_handoff;
create temporary table revoke_handoff as select public.gldd_request_handoff(day,b,c,array[ready_stop],'Vehicle issue','Fixture meeting') as id from handoff_test;
update public.bjta_staff set active=false where user_id=(select c from handoff_test);
select set_config('request.jwt.claim.sub',c::text,true) from handoff_test;
select pg_temp.expect_error(format('select public.gldd_decide_handoff(%L,%L,true)',id,'accepted'),'Handoff access required') from revoke_handoff;
select set_config('request.jwt.claim.sub',b::text,true) from handoff_test;
select public.gldd_decide_handoff(id,'cancelled',false) from revoke_handoff;
select set_config('request.jwt.claim.sub',outsider::text,true) from handoff_test;
select pg_temp.expect_error(format('select public.gldd_decide_handoff(%L,%L,true)',id,'accepted'),'Handoff access required') from first_handoff;
set local role authenticated;
do $$begin if exists(select 1 from public.gldd_handoffs) then raise exception 'Cross-workspace handoff leaked';end if;end$$;
reset role;
do $$declare original jsonb;current_value jsonb;begin select value into original from original_completed;select to_jsonb(d) into current_value from public.bjta_deliveries d join handoff_test t on d.id=t.done_stop;if original is distinct from current_value then raise exception 'Completed record changed';end if;if not exists(select 1 from public.bjta_events e join handoff_test t on e.delivery_id=t.first_stop where action='handoff_accepted' and actor_id=t.b) then raise exception 'Missing acceptance audit';end if;end$$;
select 'PASS: two-stop acceptance, food receipt, paused writes, exclusive recipient, reassignment, paid completion, duplicate prevention, decline, cancellation, revoked recipient, cross-workspace privacy, immutable completed record, audit; rollback only' as verification;
rollback;
